source("common.R")
library(DBI); suppressMessages(library(dplyr))
con <- dbConnect(spark_driver(), URL)
cat("## dbplyr vs DBI string routes\n")
df <- data.frame(id = 1:5, s = c("back\\slash", "C:\\new\\table", "tab\\there", "100\\%", "plain"), stringsAsFactors = FALSE)
dbWriteTable(con, "zzr1", df, temporary = TRUE, overwrite = TRUE)
r1 <- dbReadTable(con, "zzr1"); cat("dbWriteTable round trip identical:", identical(r1$s, df$s), "\n")
tb <- tbl(con, "zzr1")
for (v in df$s) cat(sprintf("filter(s == %s) on DBI-written table -> %d rows (expect 1)\n", deparse(v), nrow(collect(filter(tb, s == !!v)))))
print(dbplyr::sql_render(filter(tb, s == "back\\slash")))
print(as.character(dbplyr::escape("back\\slash", con = con))); print(as.character(dbQuoteString(con, "back\\slash")))
print(as.data.frame(collect(transmute(tb, id, lit = "C:\\new\\table", same = s == "C:\\new\\table"))))
t2 <- copy_to(con, df, "zzr2", temporary = TRUE, overwrite = TRUE)
r2 <- as.data.frame(collect(arrange(t2, id))); print(cbind(input = df$s, copy_to = r2$s, same = df$s == r2$s))
print(environmentName(environment(getS3method("db_copy_to", "ZusparkConnection", envir = asNamespace("dbplyr")))))
print(utils::packageVersion("dbplyr"))
cat("## C-locale latin1 handled in p10\n")
cat("## parse_json_strings\n")
J <- zuspark:::parse_json_strings
cases <- c('["a","b"]', '{"a":"1","b":"2"}', '{"a":"x\\"y","b":"c\\\\"}', '{"a":""}', '{"a":null}', '{"a":1}', '{"a":"1","a":"2"}', '[]', '{}', ' {"k" : "v"} ', '["a\\/b","\\u00e9","\\ud83d\\ude00","\\ud83d","\\u12"]', '{"a":"{\\"n\\":1}"}', '["a', '{"objectName":"`x`","proposal":"`a`, `b`"}', '{"a":["x","y"]}', '{"a":{"b":"c"},"d":"e"}', 'null', '"s"', '{"":"empty key"}', '["\\n\\t\\r\\b\\f"]', '{"a":true,"b":"x"}')
for (cs in cases) { cat(cs, " => "); r <- t(J(cs), FALSE); if (!inherits(r, "err")) cat(deparse(r), "\n") }
t(J(NA)); t(J(NULL)); t(J(c("[]", "[]"))); t(J(""))
cat("## format_data_type crafted\n")
F <- zuspark:::format_data_type
t(F(list(decimal = list(scale = 2L)))); t(F(list(decimal = list(precision = 5L)))); t(F(list(decimal = list()))); t(F(list()))
t(F(list(char = list(length = 5L)))); t(F(list(var_char = list()))); t(F(list(struct = list(fields = list())))); t(F(list(struct = list())))
t(F(list(array = list()))); t(F(list(map = list(key_type = list(string = list())))))
t(F(list(year_month_interval = list(start_field = 1L, end_field = 0L)))); t(F(list(day_time_interval = list(start_field = 0L)))); t(F(list(day_time_interval = list(end_field = 1L)))); t(F(list(day_time_interval = list(start_field = 5L)))); t(F(list(year_month_interval = list())))
t(F(list(udt = list(type = "udt", sql_type = list(integer = list()))))); t(F(list(unparsed = list(data_type_string = "weird")))); t(F(list(time = list()))); t(F(list(geometry = list(srid = 3857L)))); t(F(list(geography = list())))
t(F(list(decimal = list(precision = 2^31, scale = NA)))); t(F(list(string = list(collation = "utf8_binary"))))
cat("## decoded shapes: are unset optional fields absent?\n")
P <- zuspark:::spark_pool()
b <- zuproto::proto_encode(list(decimal = list(precision = 0L, scale = 0L)), "spark.connect.DataType", P); str(zuproto::proto_decode(b, "spark.connect.DataType", P, enums = "character")); t(F(zuproto::proto_decode(b, "spark.connect.DataType", P)))
b <- zuproto::proto_encode(list(decimal = list()), "spark.connect.DataType", P); str(zuproto::proto_decode(b, "spark.connect.DataType", P)); t(F(zuproto::proto_decode(b, "spark.connect.DataType", P)))
b <- zuproto::proto_encode(list(day_time_interval = list(start_field = 0L, end_field = 0L)), "spark.connect.DataType", P); t(F(zuproto::proto_decode(b, "spark.connect.DataType", P)))
b <- zuproto::proto_encode(list(pairs = list(list(key = "a", value = ""), list(key = "b"), list(key = "", value = "x"), list(key = "a", value = "dup"))), "spark.connect.ConfigResponse", P); t(zuspark:::config_pairs(zuproto::proto_decode(b, "spark.connect.ConfigResponse", P)))
cat("## error details args\n")
e <- tryCatch(spark_sql(con, "SELECT * FROM nope_zz"), error = identity)
t(length(spark_error_details(e))); t(spark_error_details("x")); t(spark_error_details(e, con = NULL)); t(length(spark_error_details(e, con = con))); t(spark_error_details(simpleError("x")))
e2 <- e; e2$error_id <- "not-an-id"; t(spark_error_details(e2)); e2$error_id <- NA; t(spark_error_details(e2)); e2$error_id <- NULL; t(spark_error_details(e2)); e2$error_id <- c("a", "b"); t(spark_error_details(e2)); e2$error_id <- 5; t(spark_error_details(e2))
e3 <- tryCatch(spark_sql(con, "SELECT 1/0"), error = identity); t(class(e3)); e4 <- tryCatch(spark_collect(spark_sql(con, "SELECT 1/0")), error = identity); t(e4$error_class); t({d <- spark_error_details(e4); lapply(d, function(x) c(x$type[1], x$cause))})
e5 <- tryCatch(spark_collect(spark_sql(con, "SELECT raise_error('boom \"q\" {x} \\\\ zoë')")), error = identity); t(e5$message_parameters); t(e5$classes)
cat("## interrupt / info\n")
t(spark_interrupt(con)); t(spark_interrupt(con, "x")); t(names(formals(spark_interrupt))); t(zuspark_info())
dbDisconnect(con)
